const FR_MISSES = new Set();
let LANG = "en";
function setLang(l) { LANG = (l === "fr") ? "fr" : "en"; }
function getLang() { return LANG; }
function t(s) {
  if (LANG !== "fr") return s;
  if (Object.prototype.hasOwnProperty.call(FR, s)) return FR[s];
  if (typeof s === "string" && /[A-Za-z]{3}/.test(s)) FR_MISSES.add(s);
  return s;
}
function frUrl(url) {
  if (LANG !== "fr") return { url: url, english: false };
  const mapped = FR_URLS[url];
  return mapped ? { url: mapped, english: false } : { url: url, english: true };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { FR, FR_URLS, t, setLang, getLang, FR_MISSES, frUrl };
}
